import{_ as t,a0 as p,w as n,s,ao as u,I as i,x as a,a1 as l,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"8 款適合樹莓派使用的 IDE | LCTT x X-CMD","titleTemplate":false,"description":"8 款適合樹莓派使用的 IDE | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"8 款適合樹莓派使用的 IDE | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"8 款適合樹莓派使用的 IDE | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170617 Top 8 IDEs for Raspberry Pi","title":"8 款適合樹莓派使用的 IDE","tag":"201709","desc":""},"relativePath":"201709/20170617 Top 8 IDEs for Raspberry Pi.md","filePath":"[post].md"}'),d={name:"201709/20170617 Top 8 IDEs for Raspberry Pi.md"};function I(m,e,D,g,E,h){const o=p("Link");return n(),s("div",null,[e[16]||(e[16]=u('<h1 id="_8-款適合樹莓派使用的-ide" tabindex="-1">8 款適合樹莓派使用的 IDE <a class="header-anchor" href="#_8-款適合樹莓派使用的-ide" aria-label="Permalink to “8 款適合樹莓派使用的 IDE”">​</a></h1><p><img src="https://i2.wp.com/opensourceforu.com/wp-content/uploads/2017/05/LEGO_brick_robot_05.jpg?resize=700%2C479" alt=""></p><p>樹莓派是一種微型的單板電腦（SBC），已經在學校的計算機科學教學中掀起了一場革命，但同樣，它也給軟件開發者帶來了福音。目前，樹莓派獲得的知名度遠遠超出了它原本的目標市場，而且正在應用於機器人項目中。</p><p>樹莓派是一個可以運行 Linux 操作系統的微型開發板計算機，由英國樹莓派基金會開發，用來在英國和發展中國家促進學校的基礎計算機科學教育。樹莓派擁有 USB 接口，能夠支持多種即插即用外圍設備，比如鍵盤、鼠標、打印機等。它包含了一個 HDMI（高清多媒體界面）端口，可以為用户提供視頻輸出。信用卡大小的尺寸使得樹莓派非常便攜且價格便宜。僅需一個 5V 的 micro-USB 電源供電，類似於給手機用的充電器一樣。</p><p>多年來，樹莓派基金會已經推出了幾個不同版本的樹莓派產品。 第一個版本是樹莓派 1B 型，隨後是一個相對簡單便宜的 A 型。在 2014 年，基金會推出了一個增強版本 —— 樹莓派 1B+。在 2015 年，基金會推出了全新設計的版本，售價為 5 美元，命名為樹莓派 Zero。</p><p>在 2016 年 2 月，樹莓派 3B 型發佈，這也是現在可用的主要型號。在 2017 年，基金會發布了樹莓派 Zero 的新型號樹莓派 Zero W （W = wireless 無線）。</p><p>在不久的將來，一個提高了技術規格的型號將會到來，為嵌入式系統發燒友、研究員、愛好者和工程師們用其開發多種功能的實時應用提供一個穩健的平台。</p><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-1-8.jpg" alt=""></p><p><em>圖 1 ：樹莓派</em></p><h3 id="樹莓派是一個高效的編程設備" tabindex="-1">樹莓派是一個高效的編程設備 <a class="header-anchor" href="#樹莓派是一個高效的編程設備" aria-label="Permalink to “樹莓派是一個高效的編程設備”">​</a></h3><p>在給樹莓派供電後，啓動運行 LXDE 窗口管理器，用户會獲得一個完整的基於 Debian 的 Linux 操作系統，即 Raspbian。Raspbian 操作系統為用户提供了眾多自由開源的程序，涵蓋了程序設計、遊戲、應用以及教育方面。</p><p>樹莓派的官方編程語言是 Python ，並已預裝在了 Paspbian 操作系統上。結合樹莓派和 Python 的集成開發環境 IDLE3 ，可以讓程序員能夠開發各種基於 Python 的程序。</p><p>除了 Python ，樹莓派還支持多種其它語言。並且可以使用一些自由開源的 IDE （集成開發環境）。允許程序員、開發者和應用工程師在樹莓派上開發程序和應用。</p><h3 id="樹莓派上的最佳-ide" tabindex="-1">樹莓派上的最佳 IDE <a class="header-anchor" href="#樹莓派上的最佳-ide" aria-label="Permalink to “樹莓派上的最佳 IDE”">​</a></h3><p>作為一名程序員和開發者，你需要的首先就是有一個 IDE ，這是一個集成了開發者和程序員編寫、編譯和測試軟件所需的的基本工具的綜合軟件套件。IDE 包含了代碼編輯器、編譯或解釋程序和調試器，並允許開發者通過一個圖形用户界面（GUI）來訪問。IDE 的主要目的之一是提供一個整合單元來統一功能設置，減少組合多個開發工具的必要配置。</p><p>IDE 的用户界面與文字處理程序相似，在工具欄提供顏色編碼、源代碼格式化、錯誤診斷、報告以及智能代碼補全工具。IDE 被設計用來整合第三方版本控制庫如 GitHub 或 Apache Subversion 。一些 IDE 專注於特定的編程語言，支持一個匹配該編程語言的功能集，當然也有一些是支持多種語言的。</p><p>樹莓派上擁有豐富的 IDE ，為程序員提供友好界面來開發源代碼、應用程序以及系統程序。</p><p>就讓我們來探索最適合樹莓派的 IDE 吧。</p><h4 id="bluej" tabindex="-1">BlueJ <a class="header-anchor" href="#bluej" aria-label="Permalink to “BlueJ”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-2-6.jpg" alt=""></p><p><em>圖 2 ：BlueJ 的 GUI 界面</em></p><p>BlueJ 是一款致力於 Java 編程語言的 IDE ，主要是為教育目的而開發的。它也支持小型的軟件開發項目。BlueJ 由澳大利亞的莫納什大學的 Michael Kolling 和 John Rosenburg 在 2000 年作為 Blue 系統的繼任者而開發的，後來在 2009 年 3 月成為自由開源軟件。</p><p>BlueJ 提供一種學習面向對象的編程概念的高效的方式，圖形用户界面為應用程序提供像 UML 圖一樣的類結構。每一個像類、對象和函數調用這樣基於 OOPS 的概念，都可以通過基於交互的設計來表示。</p><p><strong>特性：</strong></p><ul><li><em>簡單的交互界面：</em> 與 NetBeans 或 Eclipse 這樣的專業界面相比，BlueJ 的用户界面更加簡易學。使開發者可以專注於編程而不是環境。</li><li><em>便攜：</em>  BlueJ 支持多種平台如 Windows、Linux 以及 Mac OS X ， 可以免安裝直接運行。</li><li><em>新的創新：</em> BlueJ IDE 在對象工作台、代碼塊和範圍着色方面有着大量的創新，使新手體驗到開發的樂趣。</li><li><em>強大的技術支持：</em> BlueJ 擁有一個核心功能團隊來解答疑問，並且在 24 小時內為開發者的各種問題提供解決方案。</li></ul><p><strong>最新版本：</strong> 4.0.1</p><h4 id="geany-ide" tabindex="-1">Geany IDE <a class="header-anchor" href="#geany-ide" aria-label="Permalink to “Geany IDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-3-3.jpg" alt=""></p><p><em>圖 3 ： Geany IDE 的 GUI 界面</em></p><p>Geany IDE 使用了 Scintilla 和 GTK+ 的集成開發環境支持，被認為是一個非常輕量級的基於 GUI 的文本編輯器。 Geany 的獨特之處在於它被設計為獨立於特定的桌面環境，並且僅需要較少數量的依賴包。只需要 GTK2 運行庫就可以運行。Geany IDE 支持多種編程語言如 C、C++、C#、Java、HTML、PHP、Python、Perl、Ruby、Erlang 和 LaTeX 。</p><p><strong>特性：</strong></p><ul><li>代碼自動補全和簡單的代碼導航。</li><li>高效的語法高亮和代碼摺疊。</li><li>支持嵌入式終端仿真器，擁有高度可擴展性，可以免費下載大量功能豐富的插件。</li><li>簡單的項目管理並支持多種文件類型，包括 C、Java、PHP、HTML、Python、Perl 等。</li><li>高度定製的界面，可以添加或刪除設置、欄及窗口。</li></ul><p><strong>最新版本：</strong> 1.30.1</p><h4 id="adafruit-webide" tabindex="-1">Adafruit WebIDE <a class="header-anchor" href="#adafruit-webide" aria-label="Permalink to “Adafruit WebIDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-4-3.jpg" alt=""></p><p><em>圖 4 ：Adafruit WebIDE 的 GUI 界面</em></p><p>Adafruit WebIDE 為樹莓派用户提供一個基於 Web 的界面來執行編程功能，並且允許開發者編譯多種語言的源代碼如 Python、Ruby、JavaScript 等。</p><p>Adafruit IDE 允許開發者把代碼放在 GIT 倉庫，這樣就可以通過 GitHub 在任何地方進行訪問。</p><p><strong>特性：</strong></p><ul><li>可以通過 Web 瀏覽器的 8080 端口或 80 端口進行訪問。</li><li>支持源代碼的簡單編譯和運行。</li><li>配備一個調試器和可視器來進行正確追蹤，代碼導航以及測試源代碼。</li></ul><h4 id="algoide" tabindex="-1">AlgoIDE <a class="header-anchor" href="#algoide" aria-label="Permalink to “AlgoIDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-5-2.jpg" alt=""></p><p><em>圖 5 ：AlgoIDE 的 GUI 界面</em></p><p>AlgoIDE 結合了一個腳本語言和一個 IDE 環境，它被設計用來將編程與下一步的示例一起來運行。AlgoIDE 包含了一個強大的調試器、 實時範圍管理器並且一步一步的執行代碼。針對全年齡人羣而設計，用來設計程序以及對算法進行大量的研究。</p><p>AlgoIDE 支持多種類型的語言如 C、C++、Python、Java、Smalltalk、Objective C、ActionScript 等。</p><p><strong>特性：</strong></p><ul><li>代碼自動縮進和補全。</li><li>高效的語法高亮和錯誤管理。</li><li>包含了一個調試器、範圍管理器和動態幫助系統。</li><li>支持 GUI 和傳統的 Logo 程序語言 Turtle 來進行源代碼開發。</li></ul><p><strong>最新版本：</strong> 2016-12-08 （上次更新時間）</p><h4 id="ninja-ide" tabindex="-1">Ninja IDE <a class="header-anchor" href="#ninja-ide" aria-label="Permalink to “Ninja IDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-6-1.jpg" alt=""></p><p>圖 6 ：Ninja IDE 的 GUI 界面</p><p>Ninja IDE （“Ninja-IDE Is Not Just Another IDE”的縮寫），由 Diego Sarmentero 、Horacio Duranm Gabriel Acosta 、Pedro Mourelle 和 Jose Rostango 設計，使用純 Python 編寫並且支持多種平台運行如 Linux 、Mac OS X 和 Windows 。Ninja IDE 被認為是一個跨平台的 IDE 軟件，尤其是用來設計基於 Python 的應用程序。</p><p>Ninja IDE 是非常輕量級的，並能執行多種功能如文件處理、代碼定位、跳轉行、標籤、代碼自動縮進和編輯器縮放。除了 Python ，這款 IDE 也支持幾種其他語言。</p><p><strong>特性：</strong></p><ul><li><em>高效的代碼編輯器：</em>  Ninja-IDE 被認為是最有效的代碼編輯器，因為它能執行多種功能如代碼補全和縮進，以及助手功能。</li><li><em>錯誤和 PEP8 查找器：</em>  高亮顯示文件中的靜態和 PEP8 錯誤。</li><li><em>代碼定位器：</em>  使用此功能，快速直接訪問能夠訪問的文件。用户可以使用快捷鍵 “CTRL+K” 進行輸入，IDE 會找到特定的文本。</li><li>獨特的項目管理功能以及大量的插件使得具有 Ninja-IDE 高度可擴展性。</li></ul><p><strong>最新版本：</strong> 2.3</p><h4 id="lazarus-ide" tabindex="-1">Lazarus IDE <a class="header-anchor" href="#lazarus-ide" aria-label="Permalink to “Lazarus IDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-7.jpg" alt=""></p><p>圖 7 ：Lazarus IDE 的 GUI 界面</p><p>Lazarus IDE 是由 Cliff Baeseman、Shane Miller 和 Michael A. Hess 於 1999 年 2 月 開發。它被視為是一款用於應用程序快速開發的基於 GUI 的跨平台 IDE ，使用的是 Free Pascal 編譯器。Lazarus IDE 繼承了 Free Pascal 的三個主要特性 —— 編譯速度、執行速度和交叉編譯。可以在多種操作系統上對應用程序進行交叉編譯，如 Windows 、Linux 、Mac OS X 等。</p><p>這款 IDE 由 Lazarus 組件庫組成。這些組件庫以一個單一和帶有不同的特定平台實現的統一接口的形式為開發者提供了多種配套設施。它支持“一次編寫，隨處編譯”的原則。</p><p><strong>特性：</strong></p><ul><li>強大而快速的處理各種類型的源代碼，同時支持性能測試。</li><li>易用的 GUI ，支持組件拖拽功能。可以通過 Lazarus 包文件為 IDE 添加附加組件。</li><li>使用新功能加強的 Free Pascal ，可以用來開發 Android 應用。</li><li>高可擴展性、開放源代碼並支持多種框架來編譯其他語言。</li></ul><p><strong>最新版本：</strong> 1.6.4</p><h4 id="codeblock-ide" tabindex="-1">Codeblock IDE <a class="header-anchor" href="#codeblock-ide" aria-label="Permalink to “Codeblock IDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-8.jpg" alt=""></p><p><em>圖 8 ： Codeblock IDE 界面</em></p><p>Codeblock IDE 是用 C++ 編寫的，使用了 wxWidgets 作為 GUI 庫，發佈於 2005 年。它是一款自由開源、跨平台的 IDE ，支持多種類型的編譯器如 GCC 、Clang 和 Visual C++ 。</p><p>Codeblock IDE 高度智能並且可以支持多種功能，如語法高亮、代碼摺疊、代碼補全和縮進，同時也擁有一些擴展插件來進行定製。它可以在 Windows 、Mac OS X 和 Linux 操作系統上運行。</p><p><strong>特性：</strong></p><ul><li>支持多種類型的編譯器如 GCC 、Visual C++ 、Borland C++ 、Watcom 、Intel C++ 等。主要針對 C++ 而設計，不過現在也支持其他的一些語言。</li><li>智能的調試器，允許用户通過訪問本地函數符號和參數顯示，用户自定義監視、調用堆棧、自定義內存轉儲、線程切換以及 GNU 調試接口調試程序。</li><li>支持多種功能用來從 Dev-C++ 、Visual C++ 等平台遷移代碼。</li><li>使用自定義系統和 XML 擴展文件來存儲信息。</li></ul><p><strong>最新版本：</strong> 16.01</p><h4 id="greenfoot-ide" tabindex="-1">Greenfoot IDE <a class="header-anchor" href="#greenfoot-ide" aria-label="Permalink to “Greenfoot IDE”">​</a></h4><p><img src="http://opensourceforu.com/wp-content/uploads/2017/05/Figure-9.jpg" alt=""></p><p><em>圖 9 ： Greenfoot IDE 界面</em></p><p>Greenfoot IDE 是由肯特大學的 Michael Kolling 設計。它是一款基於 Java 的跨平台 IDE ，針對中學和大學教育目的而設計。Greenfoot IDE 的功能有項目管理、代碼自動補全、語法高亮並提供一個簡易的 GUI 界面。</p><p>Greenfoot IDE 編程包括兩個主類的子類 —— World 和 Actor 。 World 表示主要執行發生的類，Actors 是已經存在且活動於 World 中的對象。</p><p><strong>特性：</strong></p><ul><li>簡單易用的 GUI ，比 BlueJ 和其他的 IDE 交互性更強。</li><li>易於新手和初學者上手。</li><li>在執行 Java 代碼方面非常強大。</li><li>支持 GNOME/KDE/X11 圖形環境。</li><li>其他功能包括項目管理、自動補全、語法高亮以及錯誤自動校正。</li></ul><p><strong>最新版本：</strong> 3.1.0</p><hr><p>作者簡介：</p><p>Anand Nayyar</p>',83)),i("p",null,[e[1]||(e[1]=a("作者是位於印度旁遮普邦的賈朗達爾學院計算機應用與 IT 系的教授助理。他熱愛開源技術、嵌入式系統、雲計算、無線傳感器網絡以及模擬器。可以在 ",-1)),l(o,{href:"mailto:anand_nayyar@yahoo.co.in"},{default:r(()=>[...e[0]||(e[0]=[a("anand_nayyar@yahoo.co.in",-1)])]),_:1}),e[2]||(e[2]=a(" 聯繫他。",-1))]),e[17]||(e[17]=i("hr",null,null,-1)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),l(o,{href:"http://opensourceforu.com/2017/06/top-ides-raspberry-pi/"},{default:r(()=>[...e[3]||(e[3]=[a("http://opensourceforu.com/2017/06/top-ides-raspberry-pi/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),l(o,{href:"http://opensourceforu.com/author/anand-nayyar/"},{default:r(()=>[...e[5]||(e[5]=[a("Anand Nayyar",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),l(o,{href:"https://github.com/softpaopao"},{default:r(()=>[...e[6]||(e[6]=[a("softpaopao",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const P=t(d,[["render",I]]);export{b as __pageData,P as default};
